/// `sts2-rs-dh30e`: Chaos rolls a 5-orb space matching C#
/// `OrbModel._validOrbs` (Lightning / Frost / Dark / Plasma /
/// **Glass**). Re-seeds `state.run_rng.combat_orbs` per iteration
/// to drive the int_exclusive range across its full window — a
/// 4-way roll would never produce Glass, a 5-way roll must.
#[test]
fn dh30e_chaos_random_pool_includes_glass_orb() {
    use sts2_core::orbs::OrbKind;
    install_pool();
    let mut seen = std::collections::HashSet::new();
    for seed in 0..200_i32 {
        let (mut state, _e) = fresh_state(CardId::Chaos, 0, 0);
        state.run_rng.combat_orbs = sts2_core::dotnet_rng::Rng::with_name(seed, "combat_orbs");
        let f = lookup(CardId::Chaos).expect("registered");
        let _ = f(&mut state, None);
        for orb in &state.player.orbs.slots {
            seen.insert(OrbKind::of(orb));
        }
    }
    assert!(
        seen.contains(&OrbKind::Glass),
        "Chaos must be able to channel Glass; saw kinds {seen:?}"
    );
}
