/// Coverage: install_pool registers all 88 Defect handlers.
#[test]
fn install_pool_registers_88_defect_cards() {
    install_pool();
    let defect_ids: Vec<CardId> = CardId::all()
        .iter()
        .copied()
        .filter(|&id| sts2_core::cards::character_of(id) == "defect")
        .collect();
    assert_eq!(defect_ids.len(), 88, "expected 88 Defect CardIds");
    for id in defect_ids {
        assert!(lookup(id).is_some(), "Defect {id:?} not registered");
    }
}

