/// Sunder's on-kill +3 energy fires only on the alive->dead transition
/// (C# `Creature.LoseHpInternal` `WasTargetKilled`). A killing blow refunds;
/// a hit onto an already-dead target (echo/HistoryCourse replay onto a corpse
/// still in `creatures`) must NOT (defect-misc-singles fix B, seed 4365).
#[test]
fn sunder_grants_energy_only_on_the_killing_blow_not_a_corpse() {
    install_pool();
    // Killing blow: enemy at 10 HP, Sunder 24 → dies, +3 energy.
    let (mut state, euid) = fresh_state(CardId::Sunder, 24, 0);
    state.creatures[0].current_hp = 10;
    state.player.energy = 0;
    let f = lookup(CardId::Sunder).expect("registered");
    let r = f(&mut state, Some(euid));
    assert_eq!(r, EffectResult::Resolved);
    assert!(
        state.creatures[0].current_hp <= 0,
        "Sunder 24 kills a 10-HP enemy"
    );
    assert_eq!(state.player.energy, 3, "killing blow refunds +3 energy");

    // Corpse: enemy already at 0 HP before the hit → no refund.
    let (mut state2, euid2) = fresh_state(CardId::Sunder, 24, 0);
    state2.creatures[0].current_hp = 0;
    state2.player.energy = 0;
    let _ = lookup(CardId::Sunder).expect("registered")(&mut state2, Some(euid2));
    assert_eq!(
        state2.player.energy, 0,
        "a hit onto an already-dead target grants no energy"
    );
}

