/// Bead `sts2-rs-t8ob7`: Uproar's auto-play half. After the 6×2 hit it
/// picks one **Attack** from the draw pile (StableShuffle, FirstOrDefault)
/// and auto-plays it; a Skill in the draw pile is NOT eligible. Draw =
/// [DefendDefect (Skill), StrikeDefect (Attack, 6)]: Uproar deals 12, then
/// auto-plays the Strike for 6 → enemy 100 - 12 - 6 = 82; the Strike leaves
/// the draw pile while the Skill stays.
/// A killing Uproar does not auto-play its pick: C# `CardCmd.AutoPlay`
/// returns when combat `IsOverOrEnding` (CardCmd.cs:54). Defect act23 1012.
#[test]
fn play_uproar_lethal_leaves_the_pick_in_the_draw_pile() {
    install_pool();
    let (mut state, euid) = fresh_state(CardId::Uproar, 6, 0);
    state.creatures[0].current_hp = 5;
    let strike_uid = sts2_core::CardUid(NonZeroU32::new(2).expect("nz"));
    state.cards.push(Card {
        uid: strike_uid,
        card_id: CardId::StrikeDefect,
        cost: sts2_core::CardEnergyCost::new(1),
        card_type: CardType::Attack,
        target_type: TargetType::Enemy,
        upgraded: false,
        base_damage: 6,
        base_block: 0,
        ..Card::pod_defaults()
    });
    state.player.draw.push(strike_uid);
    let f = lookup(CardId::Uproar).expect("registered");
    let _ = f(&mut state, Some(euid));
    assert!(
        state.player.draw.contains(&strike_uid),
        "no auto-play after the kill"
    );
}

#[test]
fn play_uproar_auto_plays_an_attack_from_draw_not_a_skill() {
    install_pool();
    let (mut state, euid) = fresh_state(CardId::Uproar, 6, 0);

    // uid 2: a Skill in the draw pile (ineligible for Uproar's Attack pick).
    let skill_uid = sts2_core::CardUid(NonZeroU32::new(2).expect("nz"));
    state.cards.push(Card {
        uid: skill_uid,
        card_id: CardId::DefendDefect,
        cost: sts2_core::CardEnergyCost::new(1),
        card_type: CardType::Skill,
        target_type: TargetType::Self_,
        upgraded: false,
        base_damage: 0,
        base_block: 5,
        ..Card::pod_defaults()
    });
    state.player.draw.push(skill_uid);

    // uid 3: an Attack in the draw pile (the only eligible pick).
    let strike_uid = sts2_core::CardUid(NonZeroU32::new(3).expect("nz"));
    state.cards.push(Card {
        uid: strike_uid,
        card_id: CardId::StrikeDefect,
        cost: sts2_core::CardEnergyCost::new(1),
        card_type: CardType::Attack,
        target_type: TargetType::Enemy,
        upgraded: false,
        base_damage: 6,
        base_block: 0,
        ..Card::pod_defaults()
    });
    state.player.draw.push(strike_uid);

    let f = lookup(CardId::Uproar).expect("registered");
    let r = f(&mut state, Some(euid));
    assert_eq!(r, EffectResult::Resolved);

    assert_eq!(
        state.creatures[0].current_hp, 82,
        "Uproar 6×2=12 then auto-played Strike 6 → 100-18"
    );
    assert!(
        !state.player.draw.contains(&strike_uid),
        "the auto-played Attack left the draw pile"
    );
    assert!(
        state.player.draw.contains(&skill_uid),
        "the Skill was not eligible and stays in the draw pile"
    );
}

/// v0.111.0 Scrape discards a drawn unplayable Infection: its cost -1 is a
/// negative base, which `GetWithModifiers(All)` returns unclamped
/// (CardEnergyCost.cs:101-104), so `!= 0` holds. The 0-cost Claw stays.
/// Defect QX197 (v0.111.0).
#[test]
fn scrape_v0111_discards_a_drawn_unplayable_status() {
    install_pool();
    for version in [
        sts2_core::GameVersion::V0_107_1,
        sts2_core::GameVersion::V0_111_0,
    ] {
        let (mut state, euid) = fresh_state(CardId::Scrape, 7, 0);
        state.game_version = version;
        let infection = sts2_core::CardUid(NonZeroU32::new(2).expect("nz"));
        state.cards.push(Card {
            uid: infection,
            card_id: CardId::Infection,
            cost: sts2_core::CardEnergyCost::new(-1),
            card_type: CardType::Status,
            target_type: TargetType::None,
            ..Card::pod_defaults()
        });
        let claw = sts2_core::CardUid(NonZeroU32::new(3).expect("nz"));
        state.cards.push(Card {
            uid: claw,
            card_id: CardId::Claw,
            cost: sts2_core::CardEnergyCost::new(0),
            card_type: CardType::Attack,
            target_type: TargetType::Enemy,
            base_damage: 3,
            ..Card::pod_defaults()
        });
        state.player.draw.extend([infection, claw]);
        let f = lookup(CardId::Scrape).expect("registered");
        assert_eq!(f(&mut state, Some(euid)), EffectResult::Resolved);
        assert!(
            state.player.discard.contains(&infection),
            "{version:?}: Infection is discarded"
        );
        assert!(state.player.hand.contains(&claw), "{version:?}: Claw stays");
    }
}

/// Scrape discards only the cards ITS OWN draw returned (C# `Scrape.cs`:
/// `(await CardPileCmd.Draw(..)).Where(..)`). Under Iteration, the first
/// Status drawn fires `IterationPower.AfterCardDrawn`, whose nested
/// `CardPileCmd.Draw(Amount)` runs inside the per-card loop: those cards land
/// between Scrape's own draws and are not part of Scrape's result, so they
/// stay in hand even when they cost energy. Defect act-2 checkpoint branch
/// (v0.111.0 `Defect-1001-a0-act2#b1`, step 298).
#[test]
fn scrape_keeps_cards_drawn_by_iteration() {
    install_pool();
    for version in [
        sts2_core::GameVersion::V0_107_1,
        sts2_core::GameVersion::V0_111_0,
    ] {
        let (mut state, euid) = fresh_state(CardId::Scrape, 7, 0);
        state.game_version = version;
        // Draw pile top -> bottom: Dazed (Status), then five 1-cost attacks.
        let mut pile = Vec::new();
        for (n, id) in [
            CardId::Dazed,
            CardId::Dualcast,
            CardId::Zap,
            CardId::Leap,
            CardId::SweepingBeam,
            CardId::Coolheaded,
        ]
        .into_iter()
        .enumerate()
        {
            let uid = sts2_core::CardUid(NonZeroU32::new(n as u32 + 2).expect("nz"));
            let status = id == CardId::Dazed;
            state.cards.push(Card {
                uid,
                card_id: id,
                cost: sts2_core::CardEnergyCost::new(if status { -1 } else { 1 }),
                card_type: if status {
                    CardType::Status
                } else {
                    CardType::Attack
                },
                target_type: TargetType::None,
                ..Card::pod_defaults()
            });
            pile.push(uid);
        }
        state.player.draw.extend(pile.iter().copied());
        let pid = NonZeroU32::new(99).expect("nz");
        state.powers.push(sts2_core::Power::new(
            pid,
            sts2_core::PowerKind::Iteration,
            2,
        ));
        state.player.powers.push(sts2_core::PowerUid(pid));

        let f = lookup(CardId::Scrape).expect("registered");
        assert_eq!(f(&mut state, Some(euid)), EffectResult::Resolved);
        // Scrape's own draws: Dazed, then (after Iteration pulled Dualcast and
        // Zap) Leap, Sweeping Beam, Coolheaded. All cost energy: discarded.
        let (dazed, dualcast, zap) = (pile[0], pile[1], pile[2]);
        for own in [dazed, pile[3], pile[4], pile[5]] {
            assert!(
                state.player.discard.contains(&own),
                "{version:?}: own draw {own:?} discarded"
            );
        }
        assert!(
            state.player.hand.contains(&dualcast),
            "{version:?}: Iteration's Dualcast stays"
        );
        assert!(
            state.player.hand.contains(&zap),
            "{version:?}: Iteration's Zap stays"
        );
    }
}

/// Scrape filters the result of the WHOLE `CardPileCmd.Draw` (Scrape.cs
/// OnPlay, both builds): a draw that reshuffles into a Stratagem pick
/// suspends, and the discard waits until the resumed draw finishes, taking
/// the cards drawn after the pick too, but not the pick itself (Stratagem
/// moves it to hand; it is not part of the draw's result). Defect loadout
/// v0.107.1 seed 1027.
#[test]
fn scrape_discard_waits_for_a_stratagem_suspended_draw() {
    install_pool();
    for version in [
        sts2_core::GameVersion::V0_107_1,
        sts2_core::GameVersion::V0_111_0,
    ] {
        let (mut state, euid) = fresh_state(CardId::Scrape, 7, 0);
        state.game_version = version;
        let mut uids = Vec::new();
        for (n, id) in [CardId::Zap, CardId::Leap, CardId::Coolheaded]
            .into_iter()
            .enumerate()
        {
            let uid = sts2_core::CardUid(NonZeroU32::new(n as u32 + 2).expect("nz"));
            state.cards.push(Card {
                uid,
                card_id: id,
                cost: sts2_core::CardEnergyCost::new(1),
                card_type: CardType::Skill,
                target_type: TargetType::None,
                ..Card::pod_defaults()
            });
            uids.push(uid);
        }
        let zap = uids[0];
        state.player.draw.push(zap);
        state.player.discard.extend([uids[1], uids[2]]);
        let pid = NonZeroU32::new(99).expect("nz");
        state.powers.push(sts2_core::Power::new(
            pid,
            sts2_core::PowerKind::Stratagem,
            1,
        ));
        state.player.powers.push(sts2_core::PowerUid(pid));

        let f = lookup(CardId::Scrape).expect("registered");
        assert_eq!(f(&mut state, Some(euid)), EffectResult::Resolved);
        assert!(
            state.pending_choice.is_some(),
            "{version:?}: Stratagem pick open"
        );
        assert!(
            state.player.hand.contains(&zap),
            "{version:?}: no discard before the draw finishes"
        );
        let pick = state.pending_choice.as_ref().expect("open").options[0]
            .card_uid
            .expect("uid");
        let mut sel: SmallVec<[u8; 4]> = SmallVec::new();
        sel.push(0);
        let _ = sts2_core::apply(
            &mut state,
            sts2_core::Action::ResolveChoice { selection: sel },
        );
        assert!(state.pending_choice.is_none(), "{version:?}: pick resolved");
        let resumed = uids[1..]
            .iter()
            .copied()
            .find(|&u| u != pick)
            .expect("the other reshuffled card");
        assert!(
            state.player.hand.contains(&pick),
            "{version:?}: the Stratagem pick is not Scrape's to discard"
        );
        for own in [zap, resumed] {
            assert!(
                state.player.discard.contains(&own),
                "{version:?}: Scrape's draw {own:?} discarded"
            );
        }
    }
}

/// A Scrape draw resumed after a Stratagem pick still discards only its own
/// cards: the resumed draw's first Status fires Iteration, whose nested draw
/// lands in hand between Scrape's cards and is not part of Scrape's result
/// (Defect v0.107.1 5679 @553: Rust discarded the Uproar Iteration drew).
#[test]
fn resumed_scrape_draw_keeps_the_card_iteration_drew() {
    install_pool();
    for version in [
        sts2_core::GameVersion::V0_107_1,
        sts2_core::GameVersion::V0_111_0,
    ] {
        let (mut state, euid) = fresh_state(CardId::Scrape, 7, 0);
        state.game_version = version;
        let mut uids = Vec::new();
        for (n, id) in [CardId::Zap, CardId::Dazed, CardId::Dazed, CardId::Leap]
            .into_iter()
            .enumerate()
        {
            let uid = sts2_core::CardUid(NonZeroU32::new(n as u32 + 2).expect("nz"));
            let status = id == CardId::Dazed;
            state.cards.push(Card {
                uid,
                card_id: id,
                cost: sts2_core::CardEnergyCost::new(if status { -1 } else { 1 }),
                card_type: if status {
                    CardType::Status
                } else {
                    CardType::Skill
                },
                target_type: TargetType::None,
                ..Card::pod_defaults()
            });
            uids.push(uid);
        }
        let (zap, leap) = (uids[0], uids[3]);
        state.player.draw.push(zap);
        state.player.discard.extend([uids[1], uids[2], leap]);
        for (n, kind) in [
            sts2_core::PowerKind::Stratagem,
            sts2_core::PowerKind::Iteration,
        ]
        .into_iter()
        .enumerate()
        {
            let pid = NonZeroU32::new(90 + n as u32).expect("nz");
            state.powers.push(sts2_core::Power::new(pid, kind, 1));
            state.player.powers.push(sts2_core::PowerUid(pid));
        }

        let f = lookup(CardId::Scrape).expect("registered");
        assert_eq!(f(&mut state, Some(euid)), EffectResult::Resolved);
        let choice = state.pending_choice.as_ref().expect("Stratagem pick open");
        let at = choice
            .options
            .iter()
            .position(|o| o.card_uid == Some(leap))
            .expect("Leap offered");
        let mut sel: SmallVec<[u8; 4]> = SmallVec::new();
        sel.push(u8::try_from(at).expect("small"));
        let _ = sts2_core::apply(
            &mut state,
            sts2_core::Action::ResolveChoice { selection: sel },
        );
        assert!(state.pending_choice.is_none(), "{version:?}: pick resolved");
        // Scrape's resumed draw took one Dazed (firing Iteration), Iteration
        // drew the other, then the pile ran dry.
        let in_hand: Vec<_> = uids[1..3]
            .iter()
            .copied()
            .filter(|u| state.player.hand.contains(u))
            .collect();
        assert_eq!(
            in_hand.len(),
            1,
            "{version:?}: Iteration's Dazed stays, Scrape's is discarded"
        );
        assert!(state.player.discard.contains(&zap), "{version:?}");
        assert!(
            state.player.hand.contains(&leap),
            "{version:?}: the pick stays"
        );
    }
}

