/// Resolve the amount of a *player-owned* power by kind, via the
/// `player.powers` UID list into the global `powers` table.
fn player_power_amount(state: &CombatState, kind: PowerKind) -> i32 {
    state
        .player
        .powers
        .iter()
        .filter_map(|uid| state.powers.get_by_id(uid.0))
        .find(|p| p.kind == kind)
        .map_or(0, |p| p.amount)
}

