/// Synchronize applies `SynchronizePower` to self with amount
/// `2 × distinctOrbTypes` (C# `CalculationBase(0) + CalculationExtra(2) ×
/// group-by-orb-id count`). `sts2-rs-09fbz` replaced the wrong
/// evoke-front-orb port; this pin also guards the `×2` factor that is
/// easy to drop from the bead's loose "distinct orb count" summary.
/// Here we channel Lightning + Lightning + Frost → 2 distinct types →
/// amount 4.
#[test]
fn play_synchronize_applies_2x_distinct_orb_types() {
    install_pool();
    let (mut state, _) = fresh_state(CardId::Synchronize, 0, 0);
    orbs::channel_orb(&mut state, Orb::lightning());
    orbs::channel_orb(&mut state, Orb::lightning());
    orbs::channel_orb(&mut state, Orb::frost());
    assert_eq!(state.player.orbs.distinct_kinds(), 2);
    let filled_before = state.player.orbs.filled_len();
    let f = lookup(CardId::Synchronize).expect("registered");
    let r = f(&mut state, None);
    assert_eq!(r, EffectResult::Resolved);
    assert_eq!(
        player_power_amount(&state, PowerKind::Synchronize),
        4,
        "2 × 2 distinct orb types"
    );
    // sts2-rs-tgnb1: TemporaryFocusPower (IsPositive=true) folds
    // +4 Focus on the player alongside the Synchronize marker.
    assert_eq!(
        player_power_amount(&state, PowerKind::Focus),
        4,
        "Synchronize folds matching Focus stacks"
    );
    // No orb was evoked — the queue is untouched.
    assert_eq!(state.player.orbs.filled_len(), filled_before);
}

