/// Scavenge opens a player-choice `ExhaustFromHand` (C# `CardSelectCmd
/// .FromHand`) and defers the `EnergyNextTurn` grant to the post-choice
/// effect, applying it once the exhaust resolves.
#[test]
fn scavenge_opens_exhaust_choice_then_applies_energy() {
    install_pool();
    let (mut state, _) = fresh_state(CardId::Scavenge, 0, 0);
    // Add TWO hand cards so the exhaust choice is a real selection that
    // surfaces (a single candidate would auto-resolve inline, matching C#
    // `FromHand`'s `Count <= MinSelect` auto-select).
    for nz in [2u32, 3u32] {
        let hand_uid = NonZeroU32::new(nz).expect("nz");
        state.cards.push(Card {
            uid: sts2_core::CardUid(hand_uid),
            card_id: CardId::StrikeDefect,
            cost: sts2_core::CardEnergyCost::new(1),
            card_type: CardType::Attack,
            target_type: TargetType::Enemy,
            upgraded: false,
            base_damage: 6,
            base_block: 0,
            ..Card::pod_defaults()
        });
        state.player.hand.push(sts2_core::CardUid(hand_uid));
    }

    let f = lookup(CardId::Scavenge).expect("registered");
    f(&mut state, None);
    let pc = state
        .pending_choice
        .as_ref()
        .expect("exhaust choice opened");
    assert_eq!(pc.kind, sts2_core::ChoiceKind::ExhaustFromHand);
    assert_eq!(pc.min_select, 1);
    assert_eq!(
        player_power_amount(&state, PowerKind::EnergyNextTurn),
        0,
        "energy deferred to the post-choice effect",
    );

    // Resolve → exhaust the chosen card + apply the deferred energy.
    let mut sel: smallvec::SmallVec<[u8; 4]> = smallvec::SmallVec::new();
    sel.push(0);
    let _ = sts2_core::apply(
        &mut state,
        sts2_core::Action::ResolveChoice { selection: sel },
    );
    assert_eq!(state.player.exhaust.len(), 1, "chosen card exhausted");
    assert_eq!(
        player_power_amount(&state, PowerKind::EnergyNextTurn),
        2,
        "EnergyNextTurn applied after the choice resolves",
    );
}

