/// Hyperbeam's self-debuff is a **negative** Focus apply (C#
/// `Hyperbeam.cs:57` — `PowerCmd.Apply<FocusPower>(player, -3, ...)`).
/// `FocusPower.AllowNegative => true` and
/// `PowerModel.ShouldRemoveDueToAmount` keeps it at any non-zero amount,
/// so a fresh player ends with a real `Focus = -3` power instance (the
/// unsigned `apply_power_to_player` early-returns on `amount <= 0` and
/// would silently drop it, leaving 0 player powers vs C#'s 1).
#[test]
fn play_hyperbeam_applies_negative_focus() {
    install_pool();
    let (mut state, _) = fresh_state(CardId::Hyperbeam, 28, 0);
    let f = lookup(CardId::Hyperbeam).expect("registered");
    f(&mut state, None);
    assert_eq!(
        player_power_amount(&state, PowerKind::Focus),
        -3,
        "Hyperbeam applies Focus = -3 to the player"
    );
    assert_eq!(
        state.player.powers.len(),
        1,
        "the negative Focus persists as a single real player power"
    );
}

// ---- Deep pin #1: Reboot deck-wide reshuffle semantics ----
/// Reboot's spec encodes cost=0 / Skill / Self_ / Exhaust; the handler is
/// a marker until deck-wide shuffle primitives exist (P7+). Pin locks
/// the spec values + that the handler is registered + that playing it
/// on an empty state is a Resolved no-op (no panic, no draw mutation).
/// Sibling P7-7 lands the real body without changing this signature.
#[test]
fn reboot_deep_pin_deck_wide_reshuffle_semantics() {
    install_pool();
    let s = crate::cards::defect::reboot::spec();
    assert_eq!(s.cost, 0, "Reboot costs 0 (Python pin)");
    assert_eq!(s.card_type, CardType::Skill);
    assert_eq!(s.target_type, TargetType::Self_);
    // Exhaust keyword is part of the spec.
    let f = lookup(CardId::Reboot).expect("registered");
    let (mut state, _) = fresh_state(CardId::Reboot, 0, 0);
    let pre_draw = state.player.draw.len();
    let pre_discard = state.player.discard.len();
    let pre_hand = state.player.hand.len();
    let r = f(&mut state, None);
    assert_eq!(r, EffectResult::Resolved);
    // No reshuffle happens yet (handler is a marker). Pile sizes
    // unchanged. When P7+ lands the real body this pin will need a
    // deliberate bump alongside the new semantics.
    assert_eq!(state.player.draw.len(), pre_draw);
    assert_eq!(state.player.discard.len(), pre_discard);
    assert_eq!(state.player.hand.len(), pre_hand);
    assert_eq!(state.creatures[0].current_hp, 100);
}

// ---- Deep pin #2: Glacier 3-Frost channel (orb deferred) ----
/// Glacier's canonical effect: gain 6 block + channel 2 Frost orbs.
/// (Some pin variants use "channel 3 Frost"; the Python pin at
/// `01c094d` puts the block on `base_block=6`. The orb channel is
/// DEFERRED to P7-7 — we lock spec values + the block-component-only
/// behavior here, so that retrofit can simply add the channel call
/// after `gain_block_player`.)
#[test]
fn glacier_deep_pin_frost_channel_semantics() {
    install_pool();
    let s = crate::cards::defect::glacier::spec();
    assert_eq!(s.cost, 2, "Glacier costs 2 (Python pin)");
    assert_eq!(s.card_type, CardType::Skill);
    assert_eq!(s.target_type, TargetType::Self_);
    assert_eq!(s.base_block, 6, "Glacier base block = 6 (Python pin)");
    let f = lookup(CardId::Glacier).expect("registered");
    let (mut state, _) = fresh_state(CardId::Glacier, 0, 6);
    let r = f(&mut state, None);
    assert_eq!(r, EffectResult::Resolved);
    // Block component lands now; orb channel is the P7-7 retrofit.
    assert_eq!(state.player.block, 6);
}

