#[test]
fn play_quadcast_repeat_evokes_front_orb_four_times() {
    install_pool();
    let (mut state, _) = fresh_state(CardId::Quadcast, 0, 0);
    // 5-slot belt so channeling four Frost orbs does not overflow-evoke
    // the front one (the default 3-slot belt would).
    state.player.orbs = sts2_core::OrbSlots::with_capacity(5);
    // Channel four Frost orbs. C# Quadcast (`OrbEvokeType.Front`,
    // `RepeatVar(4)`) repeat-evokes the SAME front orb four times and
    // consumes it ONCE (`EvokeNext(dequeue: i == 3)`), NOT four distinct
    // orbs. So the front Frost fires 4× (4 × 5 = 20 block) and exactly
    // one orb leaves the belt — three Frost orbs remain.
    for _ in 0..4 {
        orbs::channel_orb(&mut state, Orb::frost());
    }
    let f = lookup(CardId::Quadcast).expect("registered");
    f(&mut state, None);
    assert_eq!(
        state.player.orbs.count_kind(orbs::OrbKind::Frost),
        3,
        "one front orb consumed, three remain"
    );
    assert_eq!(
        state.player.block, 20,
        "front Frost evoked 4× = 4 × 5 block"
    );
}

