/// Helper: assert exactly one power of `kind` is on the player at
/// `amount`. Used by the l0be wave below to keep assertions terse.
fn assert_player_power(state: &CombatState, kind: PowerKind, amount: i32) {
    let count = state
        .powers
        .iter()
        .filter(|p| p.kind == kind && p.amount == amount)
        .count();
    assert_eq!(
        count, 1,
        "expected exactly 1 {kind:?} power at amount {amount}; powers={:?}",
        state.powers,
    );
}

