/// gh#176 regression: a Defect playing BulkUp BEFORE any orb is
/// channelled must still drop the belt 3 -> 2. The port previously left
/// the belt at capacity 0 until the first channel (the lazy
/// `channel_orb` init), so BulkUp's `OrbCmd.RemoveSlots(1)` — guarded
/// `if capacity > 0` — no-op'd pre-channel and Rust ended combat at 3
/// slots while C# had 2 (the `ORB_STATE|{ICE_LANCE,GLACIER,GLASSWORK,
/// NULL}` cascade). `start_combat` now materializes the Defect belt at
/// `BaseOrbSlotCount => 3`, so a pre-channel capacity mutation lands.
#[test]
fn gh176_bulk_up_before_channel_removes_slot_via_start_combat() {
    install_pool();
    let f = lookup(CardId::BulkUp).expect("card registered");
    let (mut state, _) = fresh_state(CardId::BulkUp, 0, 0);
    // Build path leaves the belt at capacity 0 (no channel yet)...
    assert_eq!(state.player.orbs.capacity(), 0);
    // ...but combat start seeds the Defect belt at its base of 3 slots.
    let _ = sts2_core::combat_loop::start_combat(&mut state);
    assert_eq!(
        state.player.orbs.capacity(),
        3,
        "Defect belt seeds to BaseOrbSlotCount=3 at combat start"
    );
    let _ = f(&mut state, None);
    assert_eq!(
        state.player.orbs.capacity(),
        2,
        "BulkUp removes one slot even when played before the first channel"
    );
}

