/// GH #639: the card only grants the power — the orbs come from C#
/// `TrashToTreasurePower.AfterCardGeneratedForCombat`, which fires when the
/// player then generates a Status card (Turbo -> Void, Overclock -> Burn).
#[test]
fn gh639_trash_to_treasure_power_channels_an_orb_on_a_generated_status() {
    let mut state = run_self_card(CardId::TrashToTreasure);
    assert_player_power(&state, PowerKind::TrashToTreasure, 1);
    assert_eq!(
        state.player.orbs.filled_len(),
        0,
        "no orb from the play itself"
    );

    // The TrashToTreasure card is still in the Play pile, so the spawn path's
    // `addedByPlayer` heuristic reads true — as it does for the real
    // Turbo / Overclock OnPlay that generates the status.
    let void = Card {
        uid: sts2_core::CardUid(NonZeroU32::new(u32::MAX).expect("nz")),
        card_id: CardId::Void,
        cost: sts2_core::CardEnergyCost::new(-1),
        card_type: CardType::Status,
        target_type: TargetType::None,
        upgraded: false,
        base_damage: 0,
        base_block: 0,
        ..Card::pod_defaults()
    };
    let _ = sts2_core::card_effects::spawn_card_into_pile(
        &mut state,
        void,
        sts2_core::card_effects::PileKind::Discard,
    );
    assert_eq!(
        state.player.orbs.filled_len(),
        1,
        "TrashToTreasure(1) channels one orb on the generated Void"
    );
}

/// GH #1054 (Defect seed 1016): C# `Hook.AfterCardGeneratedForCombat` runs
/// through `IterateCombatHookListeners`, which yields no listeners once combat
/// is ending (`Hook.cs:177-207`, `:395-402`). A Gunk Up whose hits kill the
/// last primary enemy still generates its Slimed (`AddGeneratedCardsToCombat`
/// only checks `!IsInProgress`), but the `CardPileCmd.Add` it calls fails on
/// `IsEnding` (CardPileCmd.cs:312), so the Slimed reaches no pile. And
/// TrashToTreasure must NOT roll
/// `GetRandomOrb(CombatOrbGeneration)`. The run-level `combat_orbs` read
/// would otherwise carry into the next combat.
#[test]
fn gh1054_trash_to_treasure_skips_orb_when_gunk_up_ends_combat() {
    install_pool();
    let f = lookup(CardId::GunkUp).expect("registered");

    // Control: the enemy survives, so the Slimed rolls one orb.
    let (mut live, euid) = fresh_state(CardId::GunkUp, 4, 0);
    apply_power_to_player(&mut live, PowerKind::TrashToTreasure, 1);
    let before = live.run_rng.combat_orbs.counter();
    let _ = f(&mut live, Some(euid));
    assert_eq!(live.player.orbs.filled_len(), 1, "live combat: one orb");
    assert_eq!(live.run_rng.combat_orbs.counter() - before, 1);

    // Lethal: the hits kill the only enemy, so combat is ending when the
    // Slimed is generated.
    let (mut state, euid) = fresh_state(CardId::GunkUp, 4, 0);
    apply_power_to_player(&mut state, PowerKind::TrashToTreasure, 1);
    state.creatures[0].current_hp = 1;
    let before = state.run_rng.combat_orbs.counter();
    let _ = f(&mut state, Some(euid));
    assert!(
        state.cards.iter().any(|c| c.card_id == CardId::Slimed),
        "the Slimed is still generated"
    );
    assert!(
        !state
            .player
            .discard
            .iter()
            .any(|u| state.cards[u.0.get() as usize - 1].card_id == CardId::Slimed),
        "but `CardPileCmd.Add` fails once combat is ending"
    );
    assert_eq!(
        state.player.orbs.filled_len(),
        0,
        "no orb once combat is ending"
    );
    assert_eq!(
        state.run_rng.combat_orbs.counter(),
        before,
        "no combat_orbs read once combat is ending"
    );
}

