#[test]
fn e0vm_modded_draws_and_bumps_slot_and_cost() {
    install_pool();
    let f = lookup(CardId::Modded).expect("registered");
    let (mut state, _) = fresh_state(CardId::Modded, 0, 0);

    // Seed a card in draw so the draw-1 has something to pull.
    let raw = u32::try_from(state.cards.len() + 1).expect("fits");
    let draw_uid = sts2_core::CardUid::new(raw).expect("non-zero");
    state.cards.push(Card {
        uid: draw_uid,
        card_id: CardId::Wound,
        cost: sts2_core::CardEnergyCost::new(1),
        card_type: CardType::Status,
        target_type: TargetType::Self_,
        upgraded: false,
        base_damage: 0,
        base_block: 0,
        ..Card::pod_defaults()
    });
    state.player.draw.push(draw_uid);

    let played_uid = *state.player.play.last().expect("Modded was pushed");
    let played_idx = played_uid.0.get() as usize - 1;
    let cost_before = state.cards[played_idx].local_cost();
    // Fresh combat belt is lazily capacity-0; C# `AddSlots` stacks on the
    // Defect base (3), so the first MODDED yields 3 + 1 = 4 (NOT 1 — the prior
    // port capped a fresh belt at 1, Defect fuzz seed 188).
    assert_eq!(
        state.player.orbs.capacity(),
        0,
        "fresh belt starts capacity-0"
    );
    let hand_before = state.player.hand.len();

    let _ = f(&mut state, None);

    assert_eq!(state.player.hand.len(), hand_before + 1, "draw 1");
    assert_eq!(
        state.player.orbs.capacity(),
        4,
        "Modded on a fresh belt establishes the 3-slot Defect base + 1"
    );
    assert_eq!(
        state.cards[played_idx].local_cost(),
        cost_before + 1,
        "Modded's persistent cost bumps by 1"
    );

    // Playing MODDED again on the now-established belt stacks +1 (4 -> 5).
    state.player.play.push(played_uid);
    let _ = f(&mut state, None);
    assert_eq!(
        state.player.orbs.capacity(),
        5,
        "a second Modded stacks +1 on the established belt"
    );
}

