/// Bead `sts2-rs-tesla-unpowered`: Tesla Coil fires each Lightning orb's
/// passive as an UNPOWERED zap — C# `LightningOrb.ApplyLightningDamage(...,
/// ValueProp.Unpowered, ...)` — so the player's Strength must NOT scale the
/// orb zaps. Only the card's own base hit is powered. Defect sweep seeds
/// 132/192/280 (which diverged on a negative-Strength player from Shrink).
#[test]
fn tesla_coil_lightning_passives_are_unpowered() {
    install_pool();
    // Base 3 Tesla Coil + 2 channelled Lightning orbs + player Strength +2.
    let (mut state, euid) = fresh_state(CardId::TeslaCoil, 3, 0);
    // Wire the player mirror so Strength reaches the damage path.
    let player_id = NonZeroU32::new(2).expect("nz");
    state.creatures.push(Creature {
        id: player_id,
        current_hp: 80,
        max_hp: 80,
        block: 0,
        powers: SmallVec::new(),
        species: None,
        intent: None,
        intent_history: IntentHistory::default(),
        monster_id: MonsterId("Player"),
        ai: None,
    });
    state.player.creature_uid = Some(CreatureUid(player_id));
    orbs::channel_orb(&mut state, Orb::Lightning);
    orbs::channel_orb(&mut state, Orb::Lightning);
    apply_power_to_player(&mut state, PowerKind::Strength, 2);

    let f = lookup(CardId::TeslaCoil).expect("registered");
    f(&mut state, Some(euid));

    // Base hit: 3 + 2 Strength = 5. Each Lightning zap: 3 (UNPOWERED — no
    // Strength), ×2 = 6. Total 11 → 100 - 11 = 89. (The pre-fix powered path
    // boosted each zap to 5, dealing 5 + 10 = 15 → 85.)
    assert_eq!(
        state.creatures[0].current_hp, 89,
        "base hit takes Strength (+2); the 2 Lightning zaps do not (unpowered)"
    );
}

/// Defect parity seed 82: `CreativeAiPower.BeforeHandDraw` (CreativeAiPower.cs)
/// generates `Amount` Power cards as `Amount` SEPARATE
/// `GetDistinctForCombat(count=1)` calls — i.e. `Amount` independent whole-pool
/// shuffles, NOT one shuffle taking `Amount` distinct cards. The read count
/// must therefore scale with `Amount` (one shuffle = `pool-1`
/// `combat_card_generation` reads), and the cards may repeat across iterations.
#[test]
fn creative_ai_generates_amount_power_cards_via_separate_shuffles() {
    use sts2_core::hooks::dispatch_before_hand_draw_powers;

    // Full registry (not just defect::install_pool) so the character-card
    // sampler trampoline that `dispatch_before_hand_draw_powers` calls is
    // registered.
    crate::cards::dispatch::install_default_registry();

    // Read count for a SINGLE CreativeAi generation (Amount=1).
    let (mut s1, _) = fresh_state(CardId::StrikeDefect, 0, 0);
    apply_power_to_player(&mut s1, PowerKind::CreativeAi, 1);
    let hand_before_1 = s1.player.hand.len();
    let ccg_before_1 = s1.run_rng.combat_card_generation.counter();
    dispatch_before_hand_draw_powers(&mut s1);
    let reads_1 = s1.run_rng.combat_card_generation.counter() - ccg_before_1;
    assert_eq!(
        s1.player.hand.len() - hand_before_1,
        1,
        "CreativeAi(1) adds exactly one card to hand"
    );
    assert!(
        reads_1 > 0,
        "one generation consumes the card-generation stream"
    );
    // Every generated card is a Power card (the pool is filtered to Power).
    for &uid in &s1.player.hand[hand_before_1..] {
        let c = s1.cards.iter().find(|c| c.uid == uid).expect("minted");
        assert_eq!(
            c.card_type,
            CardType::Power,
            "CreativeAi generates Power cards"
        );
    }

    // Amount=2 must do TWO separate shuffles → exactly 2× the single-gen reads,
    // and add 2 cards. (One shuffle taking 2 would read only `reads_1`.)
    let (mut s2, _) = fresh_state(CardId::StrikeDefect, 0, 0);
    apply_power_to_player(&mut s2, PowerKind::CreativeAi, 2);
    let hand_before_2 = s2.player.hand.len();
    let ccg_before_2 = s2.run_rng.combat_card_generation.counter();
    dispatch_before_hand_draw_powers(&mut s2);
    let reads_2 = s2.run_rng.combat_card_generation.counter() - ccg_before_2;
    assert_eq!(
        s2.player.hand.len() - hand_before_2,
        2,
        "CreativeAi(2) adds two cards to hand"
    );
    assert_eq!(
        reads_2,
        2 * reads_1,
        "CreativeAi(2) does TWO separate whole-pool shuffles, not one"
    );
}

/// v0.111.0 C# Compact is ONE batch `CardCmd.Transform(list)`
/// (`Compact.cs:34-46`): originals are removed first with indices recorded
/// AFTER earlier removals, then re-inserted at those indices
/// (`CardCmd.cs:384-446`). Statuses at hand positions 0, 1, 4 therefore
/// become Fuels at 0, 1, 2, not in place (Defect seed 1017, GH #1054 item 7).
/// v0.107.1 `Compact.cs` awaits one `CardCmd.Transform(item, fuel)` per
/// Status, so each Fuel lands in its Status's slot (Defect random-loadout
/// v0.107.1 seeds 1014/1020/1023).
fn compact_transform_hand_order(version: sts2_core::GameVersion) -> Vec<CardId> {
    fn push(state: &mut CombatState, id: CardId, ty: CardType) -> sts2_core::CardUid {
        let raw = u32::try_from(state.cards.len() + 1).expect("fits");
        let uid = sts2_core::CardUid::new(raw).expect("non-zero");
        state.cards.push(Card {
            uid,
            card_id: id,
            cost: sts2_core::CardEnergyCost::new(1),
            card_type: ty,
            target_type: TargetType::Self_,
            ..Card::pod_defaults()
        });
        state.player.hand.push(uid);
        uid
    }
    install_pool();
    let f = lookup(CardId::Compact).expect("registered");
    let (mut state, _) = fresh_state(CardId::Compact, 0, 6);
    state.game_version = version;
    state.player.hand.clear();
    push(&mut state, CardId::Wound, CardType::Status);
    push(&mut state, CardId::Wound, CardType::Status);
    let cap = push(&mut state, CardId::Capacitor, CardType::Power);
    let ft = push(&mut state, CardId::FightThrough, CardType::Skill);
    push(&mut state, CardId::Wound, CardType::Status);
    let spin = push(&mut state, CardId::Zap, CardType::Skill);

    let _ = f(&mut state, None);

    let others: Vec<sts2_core::CardUid> = state
        .player
        .hand
        .iter()
        .copied()
        .filter(|u| [cap, ft, spin].contains(u))
        .collect();
    assert_eq!(others, vec![cap, ft, spin]);
    state
        .player
        .hand
        .iter()
        .map(|u| state.cards[u.0.get() as usize - 1].card_id)
        .collect()
}

#[test]
fn compact_batch_transform_clusters_fuels_like_csharp_v0111() {
    assert_eq!(
        compact_transform_hand_order(sts2_core::GameVersion::V0_111_0),
        vec![
            CardId::Fuel,
            CardId::Fuel,
            CardId::Fuel,
            CardId::Capacitor,
            CardId::FightThrough,
            CardId::Zap,
        ],
        "Fuels cluster at the C# batch-transform indices 0,0,2"
    );
}

#[test]
fn compact_transforms_in_place_one_at_a_time_v0107() {
    assert_eq!(
        compact_transform_hand_order(sts2_core::GameVersion::V0_107_1),
        vec![
            CardId::Fuel,
            CardId::Fuel,
            CardId::Capacitor,
            CardId::FightThrough,
            CardId::Fuel,
            CardId::Zap,
        ],
        "each Fuel replaces its Status in place"
    );
}

/// Every Defect energy card gains through `PlayerCmd.GainEnergy` (C#
/// `Turbo.cs`, `EnergySurge.cs`, `Sunder.cs`, `Supercritical.cs`,
/// `DoubleEnergy.cs` `OnPlay`), so `NoEnergyGainPower` zeroes the gain.
#[test]
fn defect_energy_cards_gain_nothing_under_no_energy_gain() {
    install_pool();
    for id in [
        CardId::Turbo,
        CardId::EnergySurge,
        CardId::Sunder,
        CardId::Supercritical,
        CardId::DoubleEnergy,
    ] {
        let (mut state, euid) = fresh_state(id, 99, 0);
        state.creatures[0].current_hp = 5;
        state.player.energy = 2;
        apply_power_to_player(&mut state, PowerKind::NoEnergyGain, 1);
        let _ = lookup(id).expect("registered")(&mut state, Some(euid));
        assert_eq!(
            state.player.energy, 2,
            "{id:?} gained energy under NoEnergyGain"
        );
    }
}
